import numpy as np

def distance_matrix(points: np.ndarray) -> np.ndarray:
    diff = points[:, None, :] - points[None, :, :]
    return np.sqrt((diff ** 2).sum(axis=-1))

def microscopic_weighting(D: np.ndarray) -> tuple[np.ndarray, float]:
    u = np.linalg.solve(D, np.ones(D.shape[0]))
    s = float(u.sum())
    return u / s, 1.0 / s

def energy(mu: np.ndarray, D: np.ndarray) -> float:
    """The quadratic energy mu^T D mu, which must equal the microscopic constant."""
    return float(mu @ (D @ mu))

if __name__ == "__main__":
    # Verify lam = mu^T D mu across random Euclidean configurations.
    rng = np.random.default_rng(0)
    for trial in range(5):
        n = rng.integers(3, 8)
        pts = rng.standard_normal((int(n), 2))
        D = distance_matrix(pts)
        mu, lam = microscopic_weighting(D)
        e = energy(mu, D)
        print(f"trial {trial}: n={n} lam={lam:+.6f} energy={e:+.6f} "
              f"match={np.isclose(lam, e)}")

